import { Question } from '../types';

export const NISM_CH10_DATA: Question[] = [
  { id: 10001, sec: "10.1 Price vs Value", q: "According to Seth Klarman, in capital markets the price is set by:", opts: ["the company's board of directors", "the valuer's estimate of cash flows", "the most panicked seller", "the most optimistic buyer"], ans: 2, exp: "Klarman: price is set by the most panicked seller; value is determined by cash flows and assets, which panic does not change." },
  { id: 10002, sec: "10.1 Price vs Value", q: "'Price is what you pay and Value is what you get' is a statement frequently made by:", opts: ["Gordon", "Seth Klarman", "Peter Lynch", "Warren Buffett"], ans: 3, exp: "The chapter attributes this classic definition to Warren Buffett." },
  { id: 10003, sec: "10.1 Price vs Value", q: "Which statement about price and value is correct?", opts: ["Value is fixed and does not change with circumstances", "Price is available from the stock market and known to all, whereas value depends on the valuer's evaluation at a point in time", "Value is available from the stock market and known to all, whereas price depends on the valuer's analysis", "Price and value are the same concept expressed in different units"], ans: 1, exp: "Price is an observable market reality; value is an analyst's subjective estimate at a point in time." },
  { id: 10004, sec: "10.1 Price vs Value", q: "The final output of a valuation exercise is best described as:", opts: ["an educated estimate, provided adequate due diligence has been complied with", "the last traded market price", "a legally fixed number accepted by all analysts", "a precise number obtained from a standard formula"], ans: 0, exp: "Inputs are uncertain, so the output is at best an educated estimate subject to adequate due diligence." },
  { id: 10005, sec: "10.1 Price vs Value", q: "Valuation is described in the chapter as an art as well as a science because it requires:", opts: ["a combination of knowledge, experience and professional judgment", "only information available in the stock market", "only mathematical computation", "only the application of a single approved model"], ans: 0, exp: "Arriving at a fair valuation needs knowledge, experience and professional judgment, so it is not purely mechanical." },
  { id: 10006, sec: "10.1 Price vs Value", q: "All of the following are consistent with the chapter's view on price and value EXCEPT:", opts: ["Value is an educated estimate", "Valuation requires professional judgment", "Price is known to all participants", "Value is a precise number observable in the stock market"], ans: 3, exp: "Value is an estimate, never a precise number observable directly in the stock market." },
  { id: 10007, sec: "10.1 Price vs Value", q: "Klarman says the opportunity in investing lies in finding:", opts: ["stocks with the highest market price", "businesses with no difference between price and value", "the greatest divergence between price and value while avoiding the extreme emotions of the crowd", "stocks that the crowd is buying most actively"], ans: 2, exp: "Opportunity lies in finding the greatest divergence between price and value while tuning out crowd emotions." },
  { id: 10008, sec: "10.2 Why Valuations are Required", q: "Which of the following is NOT listed in the chapter as a reason for carrying out valuations?", opts: ["Buying a business as part of an investment exercise", "Determining the exact price at which a share will trade tomorrow", "Accounting, taxation and other regulatory and legal requirements", "Mergers and acquisitions"], ans: 1, exp: "Valuation relates price to value; it does not predict the exact day-to-day market price tomorrow." },
  { id: 10009, sec: "10.2 Why Valuations are Required", q: "Valuation in the case of an equity swap is required mainly for:", opts: ["fair treatment of different sets of stakeholders", "calculating the tax payable by the lender", "deciding the credit rating of the company", "determining the dividend payout ratio"], ans: 0, exp: "Equity swaps require independent valuation to ensure fairness for merging shareholder groups." },
  { id: 10010, sec: "10.2 Why Valuations are Required", q: "Whatever the objective of a valuation, its purpose is to:", opts: ["determine the discount rate of the investor", "relate price to value and estimate whether the asset is fairly priced, over-priced or under-priced", "establish the book value of the asset only", "find the cost of creating the asset"], ans: 1, exp: "The primary purpose is always to judge whether an asset is under-priced, fairly priced, or over-priced relative to its intrinsic value." },
  { id: 10011, sec: "10.2 Why Valuations are Required", q: "Valuers typically present multiple scenarios because:", opts: ["market prices are not available for most assets", "regulations require three valuations for every asset", "they show the effect of a change in primary variables on the output value, given the limitations of the process", "a single scenario always overstates value"], ans: 2, exp: "Scenarios illustrate sensitivity to key input assumptions like growth rates and discount rates." },
  { id: 10012, sec: "10.2 Why Valuations are Required", q: "According to the chapter, valuations can be carried out for:", opts: ["only listed equity shares", "only assets, not liabilities", "only businesses that are being sold", "assets, businesses and liabilities"], ans: 3, exp: "Valuations are performed for individual assets, entire ongoing businesses, and complex liabilities." },
  { id: 10013, sec: "10.2 Why Valuations are Required", q: "A stock trades at Rs.80 while the valuer's estimate of its value is Rs.100. Based on the chapter's logic, the stock appears:", opts: ["over-priced", "impossible to classify", "fairly priced", "under-priced"], ans: 3, exp: "When market price (Rs.80) is below estimated intrinsic value (Rs.100), the stock is under-priced." },
  { id: 10014, sec: "10.3 Sources of Value in a Business", q: "Warren Buffett stated that there are only two sources of value in a business. They are:", opts: ["revenue and profit", "dividends and interest", "earnings and assets", "debt and equity"], ans: 2, exp: "Buffett: 'There are only two sources of value in a business - Earnings and Assets.'" },
  { id: 10015, sec: "10.3 Sources of Value in a Business", q: "Any asset, financial or real, generates two streams of cash flows, namely:", opts: ["periodic earnings and a final inflow on sale of the asset", "capital expenditure and depreciation", "dividends and bonus shares", "interest income and tax savings"], ans: 0, exp: "All assets generate periodic recurring earnings and a final liquidation/sale recovery inflow." },
  { id: 10016, sec: "10.3 Sources of Value in a Business", q: "For real estate, the two cash-flow streams are respectively:", opts: ["coupons and redemption value", "rental income and appreciated capital value on sale", "dividends and one-time sale proceeds", "interest and principal"], ans: 1, exp: "Rental yield during holding, plus appreciated capital realization at exit." },
  { id: 10017, sec: "10.3 Sources of Value in a Business", q: "A lender's primary consideration before lending is:", opts: ["the dividend history of the borrower", "the market value of collateral", "whether the business can generate cash flows to meet its obligations", "the book value of fixed assets"], ans: 2, exp: "Lenders check ongoing operational debt-service cash flow first; collateral is only a secondary fallback." },
  { id: 10018, sec: "10.3 Sources of Value in a Business", q: "Businesses are established to generate cash flows as earnings and, if earnings are insufficient or die down, to:", opts: ["issue bonus shares to owners", "raise the dividend payout", "switch to a cost-based valuation", "realise cash from the sale of tangible and intangible assets, including through liquidation"], ans: 3, exp: "If earnings fail, value reverts to asset liquidation." },
  { id: 10019, sec: "10.3 Sources of Value in a Business", q: "Which statement about business assets and liabilities is correct, as per the chapter?", opts: ["Liabilities can be reduced if assets realise less than book value", "Assets may be worth a lot less than their balance-sheet values, but outstanding liabilities must be settled in full", "Assets can never be worth less than their balance-sheet values", "Assets are always realised at book value, and liabilities can be scaled down proportionately"], ans: 1, exp: "Asset market values fluctuate downward, but debt claims remain fixed legal obligations due in full." },
  { id: 10020, sec: "10.4 Approaches to Valuation", q: "The three broad approaches to asset valuation in the chapter are:", opts: ["cost-based, cash-flow based (intrinsic) and selling price-based (relative)", "intrinsic, risk-neutral and real-world", "relative, absolute and liquidation", "cost-based, book-value based and tax-based"], ans: 0, exp: "The 3 core approaches: Cost-based, Cash-flow based (Intrinsic), and Relative (Selling price-based)." },
  { id: 10021, sec: "10.4 Approaches to Valuation", q: "Cost-based valuation is suitable only for a buyer who:", opts: ["is valuing an insurance company", "is a lender relying on collateral", "has a choice between buying and making the asset", "wants to trade shares for the short term"], ans: 2, exp: "Cost-based is meaningful when an acquirer has the viable alternative to 'build vs buy'." },
  { id: 10022, sec: "10.4 Approaches to Valuation", q: "Cost-based valuation is generally NOT suitable for financial investors mainly because:", opts: ["the cost of assets is never available", "most stock-market investors do not have a choice to build and run a company on their own", "it always overstates value", "it needs probability-adjusted cash flows"], ans: 1, exp: "Minority portfolio investors cannot practically construct and operate industrial plants on their own." },
  { id: 10023, sec: "10.4 Approaches to Valuation", q: "Cost-based valuation often involves technical assessment by:", opts: ["engineers", "credit-rating agencies", "actuaries", "stock-exchange officials"], ans: 0, exp: "Determining replacement costs and physical asset conditions requires engineering evaluations." },
  { id: 10024, sec: "10.4 Approaches to Valuation", q: "In risk-neutral valuation, the valuer:", opts: ["values the asset at the cost of creating it", "values the asset using prices of similar assets", "uses the most likely cash flow and adds a risk premium to the discount rate", "adjusts the cash flows by the probability of realising them and discounts them at the risk-free rate"], ans: 3, exp: "Risk-neutral adjusts the cash flows using probability weighting and discounts at the risk-free rate." },
  { id: 10025, sec: "10.4 Approaches to Valuation", q: "In real-world valuation, the valuer:", opts: ["uses only the replacement cost of assets", "applies P/E multiples of comparable companies", "multiplies cash flows by probabilities and discounts at the risk-free rate", "estimates the most likely cash flow and discounts it at the risk-free rate plus a suitable risk premium"], ans: 3, exp: "Real-world valuation uses expected cash flows discounted at a risk-adjusted discount rate (Rf + Risk Premium)." },
  { id: 10026, sec: "10.4 Approaches to Valuation", q: "Insurance companies are typically valued using:", opts: ["real-world valuation using CAPM", "risk-neutral valuation (embedded value and appraisal value)", "cost-based valuation", "EV/Sales"], ans: 1, exp: "Insurers are valued using actuarial risk-neutral techniques: Embedded Value (EV) and Appraisal Value." },
  { id: 10027, sec: "10.4 Approaches to Valuation", q: "Which statement correctly distinguishes risk-neutral from real-world valuation?", opts: ["Risk-neutral adjusts the cash flows and uses the risk-free rate; real-world uses the most likely cash flows and a rate that includes a risk premium", "Both use the risk-free rate, but real-world uses higher cash flows", "Both adjust cash flows by probabilities but use different discount rates", "Risk-neutral adds a risk premium to the rate; real-world adjusts the cash flows by probabilities"], ans: 0, exp: "Risk-neutral modifies the numerator (probabilities) and uses Rf; real-world modifies the denominator (risk premium)." },
  { id: 10028, sec: "10.4 Approaches to Valuation", q: "Risk-neutral and real-world valuation are the two categories of:", opts: ["relative valuation", "cost-based valuation", "intrinsic (cash-flow based) valuation", "liquidation valuation"], ans: 2, exp: "Both are methods under intrinsic (cash-flow based) valuation." },
  { id: 10029, sec: "10.4 Approaches to Valuation", q: "Valuing an asset on the basis of the price of other similar assets, using metrics such as P/E, P/B and EV/EBITDA, is:", opts: ["selling price-based (relative) valuation", "cost-based valuation", "risk-neutral valuation", "real-world valuation"], ans: 0, exp: "Comparing market multiples across peer firms is relative valuation." },
  { id: 10030, sec: "10.4 Approaches to Valuation", q: "A strategic investor intends to run a business for the long term and can either buy it or build one. Which approach would such an investor consider that financial investors seldom use?", opts: ["relative valuation using P/E", "dividend discount model", "risk-neutral valuation", "cost-based valuation"], ans: 3, exp: "Cost-based (replacement cost) valuation." },
  { id: 10031, sec: "10.5 DCF & Bond Logic", q: "A bond pays 9% interest annually and is redeemed at face value Rs.100,000 at the end of 10 years. The prevailing expected return for that maturity and credit quality is also 9%. The value of the bond today is:", opts: ["Rs.109,000", "Rs.100,000", "Rs.90,000", "Rs.190,000"], ans: 1, exp: "When coupon rate equals the required yield, bond price equals par value (Rs.100,000)." },
  { id: 10032, sec: "10.5 DCF & Bond Logic", q: "If the investors' expected return on the above 9% bond rises above 9%, the bond's value will be:", opts: ["unaffected", "exactly Rs.100,000", "less than Rs.100,000", "more than Rs.100,000"], ans: 2, exp: "Bond price and required yield have an inverse relationship; higher yield reduces bond value below par." },
  { id: 10033, sec: "10.5 DCF & Bond Logic", q: "If interest rates in the economy rise, the price of a bond would:", opts: ["double", "fall", "remain unchanged", "rise"], ans: 1, exp: "Bond prices fall when interest rates rise." },
  { id: 10034, sec: "10.5 DCF & Bond Logic", q: "DCF is conceptually the most appropriate approach when three things are known with certainty. All of the following are among them EXCEPT:", opts: ["the current market price of the stock", "the timings of the cash flows", "the expected rate of return of investors (discount rate)", "the stream of future cash flows"], ans: 0, exp: "Current market price is the output to evaluate, not an input into the intrinsic DCF model." },
  { id: 10035, sec: "10.5 DCF & Bond Logic", q: "The two principal factors that drive DCF valuation of a firm are:", opts: ["determining P/E and P/B", "estimating dividends and book value", "estimating expected cash flows and determining the discount rate", "finding replacement cost and liquidation value"], ans: 2, exp: "DCF is driven by expected cash-flow projections and the discount rate." },
  { id: 10036, sec: "10.5 DCF & Bond Logic", q: "When a bond is replaced by equity in the DCF framework:", opts: ["there is no cash flow to discount", "coupons become dividends and both quantum and timing remain known with certainty", "coupons become sale proceeds and redemption becomes dividends", "coupons become dividends and redemption value becomes expected sale proceeds, but their quantum and timing are uncertain"], ans: 3, exp: "For equities, coupons become dividends and redemption becomes sale proceeds, but both quantum and timing are uncertain." },
  { id: 10037, sec: "10.5 DCF & Bond Logic", q: "DCF-based business valuations come with significant error of judgment mainly because:", opts: ["free cash flows are always negative", "the discount rate is always fixed by the regulator", "the model ignores terminal value", "quantum and timings of future cash flows cannot be measured with certainty, and the models can be very sensitive to some inputs"], ans: 3, exp: "Uncertainty of future cash flows, indefinite corporate lives, and high sensitivity to terminal assumptions." },
  { id: 10038, sec: "10.5 DCF & Bond Logic", q: "Free Cash Flows (FCFs) in the chapter refer to:", opts: ["profits after tax only", "inflows over outflows at different points in time", "dividends declared by the company", "book value of assets less liabilities"], ans: 1, exp: "Net cash inflows over outflows available after meeting necessary operating expenses and reinvestments." },
  { id: 10039, sec: "10.5 DCF & Bond Logic", q: "The same 9%, 10-year bond (face Rs.100,000) is bought when investors' expected return for similar bonds has fallen to 7%. Its value will be:", opts: ["more than Rs.100,000", "zero", "exactly Rs.100,000", "less than Rs.100,000"], ans: 0, exp: "When market yield (7%) is lower than coupon (9%), the bond trades at a premium (> Rs.100,000)." },
  { id: 10040, sec: "10.5 DDM & Gordon Growth", q: "The Dividend Discount Model discounts expected future dividends at the:", opts: ["risk-free rate", "cost of debt", "cost of equity", "weighted average cost of capital"], ans: 2, exp: "Dividends belong to equity holders, so they are discounted at the Cost of Equity (Ke)." },
  { id: 10041, sec: "10.5 DDM & Gordon Growth", q: "The DDM is most suitable for:", opts: ["companies without an objective debt policy", "loss-making start-ups", "high-growth companies that have never paid a dividend", "mature companies in defensive industries paying regular and substantial dividends"], ans: 3, exp: "DDM suits stable, defensive companies with long histories of steady dividend payouts." },
  { id: 10042, sec: "10.5 DDM & Gordon Growth", q: "DDM needs estimates and assumptions because:", opts: ["equities have a theoretically perpetual life and dividends are not contractual", "cost of equity cannot be calculated", "bonds have contractual maturity", "dividends are always constant"], ans: 0, exp: "Equities have indefinite lives, and dividend payments are discretionary, not contractual." },
  { id: 10043, sec: "10.5 DDM & Gordon Growth", q: "The Gordon growth model for the fair value of a share is:", opts: ["P = k / (D1 - g)", "P = D1 / (k - g)", "P = D1 / (k + g)", "P = D1 * (k - g)"], ans: 1, exp: "Gordon Model: P = D1 / (k - g)." },
  { id: 10044, sec: "10.5 DDM & Gordon Growth", q: "In the Gordon growth model, D1 refers to:", opts: ["the dividend paid last year", "the total dividends till date", "the dividend expected at the end of the year", "the average dividend of the past five years"], ans: 2, exp: "D1 represents the next period's expected dividend (D0 * (1 + g))." },
  { id: 10045, sec: "10.5 DDM & Gordon Growth", q: "A key assumption of the Gordon growth model is that:", opts: ["g equals zero", "k equals the risk-free rate", "g is higher than k", "the growth rate g is lower than the cost of equity k"], ans: 3, exp: "Sustainable perpetual growth g must be strictly less than the discount rate k; otherwise the formula divides by zero or gives negative values." },
  { id: 10046, sec: "10.5 DDM & Gordon Growth", q: "A share is expected to pay a dividend of Rs.6 at the end of the year. Cost of equity is 12% and dividends grow perpetually at 8%. Its fair value under the Gordon model is:", opts: ["Rs.30", "Rs.150", "Rs.75", "Rs.50"], ans: 1, exp: "P = 6 / (0.12 - 0.08) = 6 / 0.04 = Rs.150." },
  { id: 10047, sec: "10.5 DDM & Gordon Growth", q: "Next year's dividend is expected to be Rs.4.5. Cost of equity is 14% and perpetual growth is 5%. Fair value per share is:", opts: ["Rs.50", "Rs.23.68", "Rs.90", "Rs.32.14"], ans: 0, exp: "P = 4.5 / (0.14 - 0.05) = 4.5 / 0.09 = Rs.50." },
  { id: 10048, sec: "10.5 DDM & Gordon Growth", q: "The expected dividend at the end of the year is Rs.10.5, cost of equity is 15% and perpetual growth rate is 5%. Fair value per share is:", opts: ["Rs.52.5", "Rs.210", "Rs.105", "Rs.70"], ans: 2, exp: "P = 10.5 / (0.15 - 0.05) = 10.5 / 0.10 = Rs.105." },
  { id: 10049, sec: "10.5 DDM & Gordon Growth", q: "The Gordon growth model is also referred to as the:", opts: ["perpetual growth model", "two-stage model", "capital asset pricing model", "free cash flow to firm model"], ans: 0, exp: "Also known as the Constant/Perpetual Growth Model." },
  { id: 10050, sec: "10.5 DDM & Gordon Growth", q: "Which of the following companies is most suitable for valuation under the DDM?", opts: ["A high-growth technology company that has never paid a dividend", "A company that retains all cash for reinvestment", "A start-up that is incurring losses", "A mature defensive-industry company paying regular and substantial dividends"], ans: 3, exp: "Mature, defensive dividend-paying firms." },
  { id: 10051, sec: "10.5 FCFE & Two-Stage Valuation", q: "DDM cannot be used for a company such as Alphabet Inc. because it:", opts: ["has no debt", "has never paid a dividend", "has a very high beta", "has negative operating cash flow"], ans: 1, exp: "Companies like Alphabet that have historically reinvested all earnings without paying dividends cannot be evaluated via DDM." },
  { id: 10052, sec: "10.5 FCFE & Two-Stage Valuation", q: "Under the FCFE model, free cash flows to equity shareholders are discounted at the:", opts: ["WACC, to give the value of the firm", "cost of debt, to give enterprise value", "cost of equity, to give the value of equity", "risk-free rate, to give the value of debt"], ans: 2, exp: "FCFE is discounted at the Cost of Equity (Ke) to arrive directly at the intrinsic value of Equity." },
  { id: 10053, sec: "10.5 FCFE & Two-Stage Valuation", q: "FCFE valuation is most likely to be useful for companies in the:", opts: ["mature phase paying substantial dividends only", "declining phase with no cash flows", "liquidation phase", "high-growth phase, using a two-stage approach"], ans: 3, exp: "Two-stage FCFE accommodates high-growth reinvestment in stage 1 and perpetual growth in stage 2." },
  { id: 10054, sec: "10.5 FCFE & Two-Stage Valuation", q: "FCFE is computed from the cash-flow statement as:", opts: ["EBIT x (1-t) + depreciation - capex", "operating cash flow + capital expenditure + interest payments", "operating cash flow - capital expenditure - interest payments +/- net borrowings (repayments)", "net profit / number of shares"], ans: 2, exp: "FCFE = Cash Flow from Operations - Capex - Debt Interest Paid +/- Net Borrowings / Repayments." },
  { id: 10055, sec: "10.5 FCFE & Two-Stage Valuation", q: "A company has operating cash flow of Rs.800, capital expenditure of Rs.300, interest payments of Rs.100 and repayment of borrowings of Rs.80. Its FCFE is:", opts: ["Rs.580", "Rs.320", "Rs.400", "Rs.480"], ans: 1, exp: "FCFE = 800 - 300 - 100 - 80 = Rs.320." },
  { id: 10056, sec: "10.5 FCFE & Two-Stage Valuation", q: "In a two-stage valuation, the value of equity equals:", opts: ["PV of FCFE during the high-growth phase + PV of the terminal value", "PV of FCFE during the high-growth phase only", "undiscounted terminal value + current book value", "PV of dividends of the last year only"], ans: 0, exp: "Total Equity Value = Present Value of High-Growth Cash Flows + Present Value of Terminal Value." },
  { id: 10057, sec: "10.5 FCFE & Two-Stage Valuation", q: "In a two-stage model, the terminal value:", opts: ["is already a present value and needs no discounting", "is ignored if growth is high", "is added to the next year's cash flow without discounting", "must be discounted further to its present value"], ans: 3, exp: "The terminal value is calculated as of the end of the projection horizon and must be discounted back to the present day." },
  { id: 10058, sec: "10.5 FCFE & Two-Stage Valuation", q: "The perpetual growth rate in the terminal stage is often capped at:", opts: ["the company's current EPS growth rate", "the risk-free rate plus beta", "the long-term nominal GDP growth rate of the markets in which the company operates", "twice the cost of equity"], ans: 2, exp: "No company can outgrow the broader macro-economy forever; terminal growth is capped at long-term GDP growth." },
  { id: 10059, sec: "10.5 FCFE & Two-Stage Valuation", q: "An alternative way to estimate terminal value is:", opts: ["sales multiplied by the tax rate", "EBITDA (or EBIT) at the end of the high-growth period multiplied by an appropriate EV/EBITDA (or EV/EBIT) multiple of comparable firms", "book value multiplied by P/B of the sector", "last year's dividend divided by the risk-free rate"], ans: 1, exp: "Using an exit multiple (e.g. EV/EBITDA of comparable mature firms) applied to the final projected earnings." },
  { id: 10060, sec: "10.5 FCFE & Two-Stage Valuation", q: "EBITDA at the end of the high-growth period is Rs.200 and the EV/EBITDA multiple of comparable firms is 8x. The terminal value (before discounting) is:", opts: ["Rs.1,600", "Rs.25", "Rs.208", "Rs.800"], ans: 0, exp: "Terminal Value = 200 * 8 = Rs.1,600." },
  { id: 10061, sec: "10.5 FCFE & Two-Stage Valuation", q: "A constant growth rate is inappropriate for a high-growth company because it:", opts: ["would be very high, unsustainable and may exceed the cost of capital", "would eliminate terminal value", "would reduce the discount rate", "would be negative"], ans: 0, exp: "Assuming permanent high growth violates economic principles and mathematical model boundaries." },
  { id: 10062, sec: "10.5 FCFE & Two-Stage Valuation", q: "A rudimentary forecast of growth extrapolates historical growth rates. Analysts refine it using judgment such as:", opts: ["the current market price and volume", "the proportion of earnings ploughed back and the return on equity", "the dividend yield and P/E", "the coupon rate and the face value"], ans: 1, exp: "Fundamental sustainable growth = Retention Ratio (Plough-back) * Return on Equity (ROE)." },
  { id: 10063, sec: "10.5 FCFF & WACC", q: "Free Cash Flow to Firm (FCFF) is discounted at the:", opts: ["cost of debt", "cost of equity", "weighted average cost of capital (WACC)", "risk-free rate"], ans: 2, exp: "FCFF represents cash flow available to all providers of capital (debt and equity), so it is discounted at WACC." },
  { id: 10064, sec: "10.5 FCFF & WACC", q: "Analysts prefer FCFF to FCFE when:", opts: ["the company pays regular and substantial dividends", "only the cost of equity is known", "the company has no debt at all and no growth", "the company has no objective debt policy, so net borrowings cannot be estimated objectively"], ans: 3, exp: "Without a predictable target leverage policy, net debt additions are volatile; FCFF bypasses debt cash flows." },
  { id: 10065, sec: "10.5 FCFF & WACC", q: "FCFF is best defined as free cash flow:", opts: ["before taking into account cash flows relating to any source of capital", "after dividend payments", "after interest and net borrowings", "available only to equity shareholders"], ans: 0, exp: "Cash flow generated by operations before debt servicing or equity payouts." },
  { id: 10066, sec: "10.5 FCFF & WACC", q: "The indirect method of computing FCFF is:", opts: ["EBIT + interest tax - dividends", "EBIT x (1 - tax rate) + depreciation and non-cash charges - increase in non-cash working capital - capital expenditure", "Net profit + depreciation - dividends", "EBITDA - interest payments + net borrowings"], ans: 1, exp: "FCFF = EBIT * (1 - t) + D&A - Increase in Non-Cash Working Capital - Capex." },
  { id: 10067, sec: "10.5 FCFF & WACC", q: "EBIT is Rs.500, tax rate 30%, depreciation Rs.100, increase in non-cash working capital Rs.40 and capital expenditure Rs.150. FCFF is:", opts: ["Rs.200", "Rs.310", "Rs.260", "Rs.410"], ans: 2, exp: "FCFF = 500 * (1 - 0.30) + 100 - 40 - 150 = 350 + 100 - 40 - 150 = Rs.260." },
  { id: 10068, sec: "10.5 FCFF & WACC", q: "While computing FCFF or FCFE, a gain on sale of assets is:", opts: ["ignored completely", "added back like depreciation", "added twice", "deducted from the cash flow"], ans: 3, exp: "Non-operating gains included in accounting profit must be deducted to reflect true recurring cash from operations." },
  { id: 10069, sec: "10.5 FCFF & WACC", q: "To go from the value of the firm to the value of equity, the chapter deducts:", opts: ["depreciation and amortisation", "minority interest, preferred share capital and interest-bearing debt", "dividends payable and tax", "only the cost of equity"], ans: 1, exp: "Value of Equity = Firm Value - Interest-bearing Debt - Preferred Capital - Minority Interest (+ Cash)." },
  { id: 10070, sec: "10.5 FCFF & WACC", q: "Firm value is Rs.10,000. Minority interest is Rs.500, preferred share capital Rs.300 and interest-bearing debt Rs.2,200. Value of equity is:", opts: ["Rs.7,300", "Rs.9,500", "Rs.9,000", "Rs.7,000"], ans: 3, exp: "Equity Value = 10,000 - 500 - 300 - 2,200 = Rs.7,000." },
  { id: 10071, sec: "10.5 FCFF & WACC", q: "In the DCF section, enterprise value is arrived at from the firm value by deducting:", opts: ["capital expenditure of the year", "interest-bearing debt only", "surplus cash, cash equivalents and short-term investments not needed for current operations", "minority interest only"], ans: 2, exp: "Enterprise Value represents core operating value, deducting non-operating surplus cash/investments." },
  { id: 10072, sec: "10.5 FCFF & WACC", q: "Which of the following statements about discount rates are correct? I. FCFF discounted at WACC. II. FCFE discounted at cost of equity. III. DDM discounts dividends at cost of equity. IV. FCFF discounted at cost of equity.", opts: ["I, II and III only", "I and IV only", "II, III and IV only", "I, II, III and IV"], ans: 0, exp: "Statement IV is false because FCFF belongs to the entire firm and must be discounted at WACC." },
  { id: 10073, sec: "10.5 FCFF & WACC", q: "For a high-growth company, an FCFF valuation:", opts: ["is also split into high-growth cash flows and terminal value", "is not possible", "uses only the terminal value", "uses only dividends"], ans: 0, exp: "FCFF models for growth companies employ explicit stage-1 projections plus a discounted terminal value." },
  { id: 10074, sec: "10.5 CAPM & Cost of Capital", q: "The three components of CAPM are:", opts: ["EBIT, capital employed and beta", "cost of debt, tax rate and weight of equity", "risk-free rate, dividend yield and P/E", "risk-free rate, expected return on a stock-market portfolio, and beta"], ans: 3, exp: "Risk-free rate (Rf), Market Return (Rm), and Beta." },
  { id: 10075, sec: "10.5 CAPM & Cost of Capital", q: "The CAPM formula for cost of equity is:", opts: ["Ke = Rf * Beta * (Rm - Rf)", "Ke = Rm + Beta * (Rf - Rm)", "Ke = Rf + Beta * (Rm - Rf)", "Ke = Beta * Rm"], ans: 2, exp: "CAPM: Ke = Rf + Beta * (Rm - Rf)." },
  { id: 10076, sec: "10.5 CAPM & Cost of Capital", q: "(Rm - Rf) is called the ____ and Beta * (Rm - Rf) is called the ____:", opts: ["market risk premium; equity risk premium", "equity risk premium; market risk premium", "systematic risk; unsystematic risk", "cost of debt; cost of equity"], ans: 0, exp: "(Rm - Rf) = Market Risk Premium; Beta * (Rm - Rf) = Equity Risk Premium." },
  { id: 10077, sec: "10.5 CAPM & Cost of Capital", q: "In the chapter, beta is used as a proxy for:", opts: ["unsystematic risk only", "systematic risk, reflecting both business and financial risks", "dividend growth", "the risk-free rate"], ans: 1, exp: "Equity beta measures undiversifiable systematic risk, capturing business operational and financial leverage risks." },
  { id: 10078, sec: "10.5 CAPM & Cost of Capital", q: "Rf = 7%, Rm = 12% and beta = 1.2. The cost of equity under CAPM is:", opts: ["12.6%", "14.4%", "13%", "19.0%"], ans: 2, exp: "Ke = 7% + 1.2 * (12% - 7%) = 7% + 6% = 13%." },
  { id: 10079, sec: "10.5 CAPM & Cost of Capital", q: "Rf = 6%, Rm = 11% and beta = 0.8. The cost of equity is:", opts: ["10%", "8.8%", "14.8%", "12.2%"], ans: 0, exp: "Ke = 6% + 0.8 * (11% - 6%) = 6% + 4% = 10%." },
  { id: 10080, sec: "10.5 CAPM & Cost of Capital", q: "The WACC formula is:", opts: ["Ke * Wd + Kd * (1 - Tx) * We", "Ke * We + Kd * (1 - Tx) * Wd", "Ke + Kd * (1 - Tx)", "Ke * We + Kd * Wd"], ans: 1, exp: "WACC = Ke * We + Kd * (1 - Tax Rate) * Wd." },
  { id: 10081, sec: "10.5 CAPM & Cost of Capital", q: "Ke = 13%, Kd = 9%, tax rate = 30%, equity weight 60% and debt weight 40%. WACC is:", opts: ["8.98%", "11.40%", "10.80%", "10.32%"], ans: 3, exp: "Equity = 0.60 * 13% = 7.80%. Debt = 0.40 * 9% * (1 - 0.30) = 2.52%. WACC = 7.80% + 2.52% = 10.32%." },
  { id: 10082, sec: "10.5 CAPM & Cost of Capital", q: "In most exercises, the cost of debt is taken as:", opts: ["the risk-free rate", "the prevailing interest rate in the economy for borrowers of comparable credit quality", "the dividend yield of the company", "the coupon rate of the company's oldest bond only"], ans: 1, exp: "The current market borrowing rate for comparable credit ratings." },
  { id: 10083, sec: "10.5 CAPM & Cost of Capital", q: "A company that wants to use FCFE for valuation should match it with which discount rate?", opts: ["after-tax cost of debt", "WACC", "cost of equity", "cost of debt"], ans: 2, exp: "Cash flow to equity (FCFE) pairs strictly with Cost of Equity (Ke)." },
  { id: 10084, sec: "10.6-10.7 Relative Valuation & Earnings Multiples", q: "Relative valuation primarily tells an analyst:", opts: ["whether something is cheap or expensive, not its absolute value", "the cost of creating the asset", "the probability-adjusted cash flows", "the exact intrinsic value"], ans: 0, exp: "Compares market pricing across peers; indicates whether an asset is relatively cheap or expensive." },
  { id: 10085, sec: "10.6-10.7 Relative Valuation & Earnings Multiples", q: "Dividend yield is calculated as:", opts: ["DPS * current price", "EPS / DPS", "current price / DPS", "DPS / current price"], ans: 3, exp: "Dividend Yield = Dividend per Share / Market Price." },
  { id: 10086, sec: "10.6-10.7 Relative Valuation & Earnings Multiples", q: "A stock pays a dividend of Rs.5 and its price is Rs.200. Its dividend yield and Price/Dividend ratio are:", opts: ["2.5% and 40x", "5% and 20x", "40% and 2.5x", "3.33% and 30x"], ans: 0, exp: "Yield = 5 / 200 = 2.5%. Price/Dividend = 200 / 5 = 40x." },
  { id: 10087, sec: "10.6-10.7 Relative Valuation & Earnings Multiples", q: "A dividend of Rs.5 is paid by a stock priced at Rs.150. Its dividend yield is:", opts: ["5%", "3.33%", "10%", "2.5%"], ans: 1, exp: "Yield = 5 / 150 = 3.33%." },
  { id: 10088, sec: "10.6-10.7 Relative Valuation & Earnings Multiples", q: "A 10% coupon bond is held by an investor in the 30% tax bracket, so post-tax return is 7%. A share pays Rs.5 dividend. At which price does the dividend yield exceed 7%?", opts: ["Rs.200", "Rs.100", "Rs.50", "Rs.150"], ans: 2, exp: "At Rs.50, dividend yield is 5/50 = 10% (> 7%). At Rs.100 it is 5%, at Rs.150 3.33%, at Rs.200 2.5%." },
  { id: 10089, sec: "10.6-10.7 Relative Valuation & Earnings Multiples", q: "According to the chapter, equity yields are generally higher than bond yields:", opts: ["only for loss-making companies", "in bull markets", "only when interest rates are zero", "when equity is cheap, typically when markets are down"], ans: 3, exp: "Equity yields exceed bond yields during severe bear markets or market bottoms when equity prices are depressed." },
  { id: 10090, sec: "10.6-10.7 Relative Valuation & Earnings Multiples", q: "Why is a high dividend yield not necessarily a value pick?", opts: ["A high payout may indicate limited avenues for expansion, limiting capital appreciation", "Dividends are contractual and hence risky", "It always means the company is over-leveraged", "High payouts always reduce the share price"], ans: 0, exp: "A very high payout may signal a mature business with zero growth prospects or an unsustainable dividend." },
  { id: 10091, sec: "10.6-10.7 Relative Valuation & Earnings Multiples", q: "Earnings yield is calculated as:", opts: ["current price / EPS", "EPS / current price", "net profit / net worth", "DPS / EPS"], ans: 1, exp: "Earnings Yield = EPS / Price (the mathematical reciprocal of P/E)." },
  { id: 10092, sec: "10.6-10.7 Relative Valuation & Earnings Multiples", q: "Price-to-earnings (P/E) ratio is calculated as:", opts: ["EPS / current price of the stock", "EPS * number of shares", "current price * EPS", "current price of the stock / EPS"], ans: 3, exp: "P/E = Market Price per Share / Earnings per Share." },
  { id: 10093, sec: "10.6-10.7 Relative Valuation & Earnings Multiples", q: "What is the earnings yield if the price of a stock is Rs.195 and EPS is Rs.13?", opts: ["0.067 percent", "0.15 percent", "6.67 percent", "15 percent"], ans: 2, exp: "Earnings Yield = 13 / 195 = 0.0667 = 6.67%." },
  { id: 10094, sec: "10.6-10.7 Relative Valuation & Earnings Multiples", q: "A stock trades at Rs.240 with EPS of Rs.12. Its P/E and earnings yield are:", opts: ["20x and 5%", "20% and 5x", "5x and 20%", "12x and 8.33%"], ans: 0, exp: "P/E = 240 / 12 = 20x. Earnings Yield = 12 / 240 = 5%." },
  { id: 10095, sec: "10.6-10.7 Relative Valuation & Earnings Multiples", q: "EPS is computed as:", opts: ["dividends / price", "net profit / number of shares", "net profit / net worth", "EBIT / capital employed"], ans: 1, exp: "EPS = Net Profit Attributable to Equity / Weighted Average Shares Outstanding." },
  { id: 10096, sec: "10.6-10.7 Relative Valuation & Earnings Multiples", q: "P/E can be interpreted as:", opts: ["the dividend received per share", "the book value per rupee of price", "the profit received for every unit invested", "the money an investor needs to invest to receive one unit of profit"], ans: 3, exp: "A P/E of 20 means investing Rs.20 to acquire rights to Rs.1 of annual profit." },
  { id: 10097, sec: "10.6-10.7 Relative Valuation & Earnings Multiples", q: "All else being equal, a company whose P/E is higher than its peers and the market P/E is:", opts: ["always undervalued", "always fairly priced", "considered expensive, though investors may pay more if above-average growth or a turnaround is expected", "always poorly managed"], ans: 2, exp: "Relatively expensive, though higher growth, governance quality, or turnaround potential may warrant the premium." },
  { id: 10098, sec: "10.6-10.7 Relative Valuation & Earnings Multiples", q: "Which of the following statements is correct about premium and discount in P/E?", opts: ["Higher risk justifies a premium", "Lower growth justifies a premium", "Higher growth potential or lesser risk lets a company trade at a premium; lower growth or higher risk at a discount", "Growth and risk have no bearing on P/E"], ans: 2, exp: "Superior growth and lower operational risk command a valuation premium; high leverage and low growth trade at a discount." },
  { id: 10099, sec: "10.6-10.7 Relative Valuation & Earnings Multiples", q: "A trailing P/E uses ____ whereas a forward P/E uses ____:", opts: ["historical EPS; forecast EPS", "dividend; earnings yield", "book value; sales", "forecast EPS; historical EPS"], ans: 0, exp: "Trailing P/E uses past 12-month earnings; Forward P/E uses next 12-month estimated earnings." },
  { id: 10100, sec: "10.6-10.7 Relative Valuation & Earnings Multiples", q: "The PEG ratio is calculated as:", opts: ["growth rate / P/E ratio", "P/E ratio / growth rate", "P/E ratio * growth rate", "EPS / growth rate"], ans: 1, exp: "PEG Ratio = (P/E Ratio) / (Expected Earnings Growth Rate %)." },
  { id: 10101, sec: "10.6-10.7 Relative Valuation & Earnings Multiples", q: "A stock has a P/E of 18 and expected EPS growth of 12%. Its PEG ratio is:", opts: ["0.67", "6", "216", "1.5"], ans: 3, exp: "PEG = 18 / 12 = 1.5." },
  { id: 10102, sec: "10.6-10.7 Relative Valuation & Earnings Multiples", q: "Company A has P/E of 12x and growth of 10%. Company B has P/E of 14x and growth of 15%. Which statement is correct?", opts: ["A is cheaper on both P/E and PEG", "PEG cannot be used to compare companies", "B is more expensive on both", "B appears more attractively priced based on PEG (0.93x vs 1.2x) even though its P/E is higher"], ans: 3, exp: "A PEG = 12/10 = 1.2x. B PEG = 14/15 = 0.93x. B offers more growth per unit of P/E multiple." },
  { id: 10103, sec: "10.6-10.7 Relative Valuation & Earnings Multiples", q: "As a rule of thumb stated in the chapter, a PEG ratio of less than 1 suggests that the business:", opts: ["may be treated as undervalued", "is certainly overvalued", "has no growth", "has negative earnings"], ans: 0, exp: "Peter Lynch rule: PEG < 1.0 may signify undervaluation relative to earnings growth." },
  { id: 10104, sec: "10.6-10.7 Relative Valuation & Earnings Multiples", q: "EV/EBIT and EV/EBITDA are preferred from an acquirer's perspective because they are:", opts: ["affected by leverage through EPS", "neutral to capital structure", "based on book value", "based on dividends"], ans: 1, exp: "Both numerator (EV) and denominator (operating earnings) belong to the entire capital structure, making the ratio capital-structure neutral." },
  { id: 10105, sec: "10.6-10.7 Relative Valuation & Earnings Multiples", q: "For capital-intensive industries, EV/EBITDA is preferred over EV/EBIT because:", opts: ["EBIT cannot be computed", "capital-intensive firms have no depreciation", "historical cost of assets and the depreciation method create major discrepancies in EBIT", "EBITDA includes interest"], ans: 2, exp: "Varying depreciation methods, useful life estimates, and asset purchase dates distort EBIT." },
  { id: 10106, sec: "10.6-10.7 Relative Valuation & Earnings Multiples", q: "Market capitalisation Rs.5,000; debt Rs.1,200; cash Rs.200; EBITDA Rs.600. EV/EBITDA is:", opts: ["8.33x", "11x", "10x", "6x"], ans: 2, exp: "EV = 5,000 + 1,200 - 200 = 6,000. EV/EBITDA = 6,000 / 600 = 10x." },
  { id: 10107, sec: "10.6-10.7 Relative Valuation & Earnings Multiples", q: "When profit is negative (a loss), the most meaningful multiple which can never be negative is:", opts: ["PEG", "EV/Sales", "EV/EBITDA", "P/E"], ans: 1, exp: "Revenues cannot be negative, so EV/Sales is used when earnings are currently negative." },
  { id: 10108, sec: "10.6-10.7 Relative Valuation & Earnings Multiples", q: "A loss-making company has no foreseeable prospect of turning profitable. Its valuation should be based on:", opts: ["PEG", "P/E", "EV/Sales", "liquidation value, because its going-concern nature is doubtful"], ans: 3, exp: "If future profitability is structurally unachievable, going-concern assumption fails and liquidation value applies." },
  { id: 10109, sec: "10.6-10.7 Relative Valuation & Earnings Multiples", q: "For a company that has just broken even, multiples such as P/E and EV/EBITDA tend to be:", opts: ["too high to be meaningful, as profit is far below its long-term potential", "very low and reliable", "negative", "unaffected"], ans: 0, exp: "Very small denominator profits create artificially astronomical multiples." },
  { id: 10110, sec: "10.8 Asset-Based Valuation Metrics", q: "ROE and ROCE are respectively computed as:", opts: ["Net profit / total assets; EBIT / sales", "Dividends / equity; interest / debt", "Net profit / equity capital (net worth); EBIT / total capital employed (debt + net worth)", "EBIT / equity; net profit / debt"], ans: 2, exp: "ROE = PAT / Net Worth; ROCE = EBIT / Capital Employed." },
  { id: 10111, sec: "10.8 Asset-Based Valuation Metrics", q: "Price-to-book value (P/B) tells an investor:", opts: ["how much needs to be invested to own a unit of net assets", "the cost of creating the asset", "how much dividend is paid per unit of price", "how much to invest to earn a unit of profit"], ans: 0, exp: "Indicates the price paid per rupee of net accounting asset backing." },
  { id: 10112, sec: "10.8 Asset-Based Valuation Metrics", q: "P/B is particularly preferred for the financial sector because:", opts: ["financial firms have no earnings", "assets are mostly monetary, so book value is close to fair value", "financial firms have no liabilities", "financial firms have the highest ROE"], ans: 1, exp: "Bank assets consist predominantly of loans and liquid securities marked close to fair value." },
  { id: 10113, sec: "10.8 Asset-Based Valuation Metrics", q: "P/B is less suitable for service and technology firms because:", opts: ["they have high depreciation", "they cannot have a book value", "they hold only monetary assets", "human capital and self-generated IP are not reflected on the balance sheet"], ans: 3, exp: "Software code, brand power, and talent are expensed and missing from tangible book value." },
  { id: 10114, sec: "10.8 Asset-Based Valuation Metrics", q: "Why does book value give a conservative value of equity?", opts: ["Accounting follows conservatism", "Balance sheets include human capital", "Assets are revalued every day", "Accounting follows market prices"], ans: 0, exp: "GAAP conservatism principles record historical cost and write down impairments while omitting unearned gains." },
  { id: 10115, sec: "10.8 Asset-Based Valuation Metrics", q: "A company has a lower P/B than its industry. Which statement reflects the chapter's guidance?", opts: ["It must be overvalued", "It may be attractively valued, but companies with higher ROE should command a premium as equity is used more efficiently", "P/B is unrelated to ROE", "ROE should be ignored"], ans: 1, exp: "A low P/B could simply reflect a terrible ROE; efficient capital allocators deserve P/B premiums." },
  { id: 10116, sec: "10.8 Asset-Based Valuation Metrics", q: "In a fragmented industry with outliers, while comparing P/B with the industry, an analyst should check:", opts: ["only the lowest multiple", "only the highest multiple", "only a single peer", "both the mean and the median multiples"], ans: 3, exp: "Both mean and median prevent distortion from extreme high/low outlier peers." },
  { id: 10117, sec: "10.8 Asset-Based Valuation Metrics", q: "Total equity is Rs.9,900 lakh (share capital 500 + premium 3,200 + reserves 6,200), shares are 50 lakh, price is Rs.200. P/B is closest to:", opts: ["0.99", "20.2", "1.01", "1.09"], ans: 2, exp: "Book Value Per Share = 9,900 / 50 = Rs.198. P/B = 200 / 198 = 1.01x." },
  { id: 10118, sec: "10.8 Asset-Based Valuation Metrics", q: "Share capital Rs.500 lakh, premium Rs.2,100 lakh, reserves Rs.5,400 lakh. Shares are 50 lakh and price is Rs.175. P/B is closest to:", opts: ["1.09", "2.19", "0.92", "1.01"], ans: 0, exp: "Total Equity = 500 + 2,100 + 5,400 = 8,000 lakh. BVPS = 8,000 / 50 = 160. P/B = 175 / 160 = 1.09x." },
  { id: 10119, sec: "10.8 Asset-Based Valuation Metrics", q: "Share capital Rs.600 lakh, premium Rs.1,400 lakh, reserves Rs.4,000 lakh; shares 40 lakh; price Rs.225. P/B is:", opts: ["3.75", "1.50", "0.67", "1.33"], ans: 1, exp: "Total Equity = 6,000 lakh. BVPS = 6,000 / 40 = Rs.150. P/B = 225 / 150 = 1.50x." },
  { id: 10120, sec: "10.8 Asset-Based Valuation Metrics", q: "Enterprise value (EV) is computed as:", opts: ["value of equity + cash", "value of debt - value of equity", "value of equity + value of debt - cash and cash equivalents", "value of equity - value of debt + cash"], ans: 2, exp: "EV = Market Value of Equity + Market Value of Debt - Cash and Cash Equivalents." },
  { id: 10121, sec: "10.8 Asset-Based Valuation Metrics", q: "Net worth Rs.100,000, debt Rs.100,000, market cap Rs.500,000, no cash, ROCE 45%. EV/Capital employed and effective return on EV are:", opts: ["2.5x and 18%", "3x and 45%", "5x and 9%", "3x and 15%"], ans: 3, exp: "Capital Employed = 200,000. EV = 500,000 + 100,000 = 600,000. EV/CE = 600k / 200k = 3x. Effective Return = 45% / 3 = 15%." },
  { id: 10122, sec: "10.8 Asset-Based Valuation Metrics", q: "In the above case, if the investor needs a minimum return of 20%, the maximum EV he can pay is:", opts: ["Rs.600,000", "Rs.450,000", "Rs.900,000", "Rs.400,000"], ans: 1, exp: "Max EV/CE = 45% / 20% = 2.25x. Max EV = 2.25 * 200,000 = Rs.450,000." },
  { id: 10123, sec: "10.8 Asset-Based Valuation Metrics", q: "Net worth Rs.150, debt Rs.250, market cap Rs.600, cash Rs.50 and ROCE 24%. The effective return on EV is:", opts: ["12%", "16%", "24%", "8%"], ans: 0, exp: "Capital Employed = 150 + 250 = 400. EV = 600 + 250 - 50 = 800. EV/CE = 800 / 400 = 2x. Effective Return = 24% / 2 = 12%." },
  { id: 10124, sec: "10.8 Asset-Based Valuation Metrics", q: "Net Asset Value (NAV) of equity is:", opts: ["the fair value of assets including off-balance-sheet items minus liabilities", "the book value of assets minus liabilities", "the market value of an entity's assets minus its liabilities", "price per share multiplied by shares outstanding"], ans: 2, exp: "NAV is the current estimated market value of assets minus liabilities." },
  { id: 10125, sec: "10.8 Asset-Based Valuation Metrics", q: "NAV is mostly used for extremely asset-oriented businesses such as:", opts: ["non-banking finance companies", "life insurance", "IT services", "real estate, shipping and aviation"], ans: 3, exp: "Asset-heavy companies like real estate development, shipping fleets, and aircraft leasing." },
  { id: 10126, sec: "10.8 Asset-Based Valuation Metrics", q: "The market value of an entity's assets is Rs.5,000 and its liabilities are Rs.3,200. If there are 50 shares, NAV per share is:", opts: ["Rs.36", "Rs.100", "Rs.16", "Rs.64"], ans: 0, exp: "Total NAV = 5,000 - 3,200 = Rs.1,800. NAV per share = 1,800 / 50 = Rs.36." },
  { id: 10127, sec: "10.8 Asset-Based Valuation Metrics", q: "Price/Embedded value is used for ____ and Price/Adjusted book value for ____:", opts: ["start-ups; aviation", "NBFCs; life insurance companies", "real estate; shipping", "life insurance companies; NBFCs"], ans: 3, exp: "P/EV is used for life insurance; P/ABV (Adjusted Book Value) is used for NBFCs with loan-loss adjustments." },
  { id: 10128, sec: "10.8 Asset-Based Valuation Metrics", q: "Adjusted book value differs from book value in that it:", opts: ["uses market capitalisation", "uses fair values of assets and liabilities and factors in off-balance-sheet items", "uses historical cost only", "ignores liabilities"], ans: 1, exp: "Factors in bad debt provisioning, fair values, and off-balance sheet liabilities." },
  { id: 10129, sec: "10.8 Asset-Based Valuation Metrics", q: "EV/Capacity is used in situations where:", opts: ["the company pays regular dividends", "the company has stable earnings", "financial metrics do not reflect potential value, such as start-ups or a steel plant currently out of operation", "the company is a bank"], ans: 2, exp: "Applied to cyclical or dormant facilities (e.g. EV per ton of steel/cement production capacity)." },
  { id: 10130, sec: "10.9-10.10 Multiples & SOTP", q: "Trading multiples are derived from:", opts: ["prices in recent acquisitions", "the cost of creating the asset", "probability-adjusted cash flows", "stock market prices of comparable companies"], ans: 3, exp: "Derived directly from real-time stock market pricing of comparable publicly traded firms." },
  { id: 10131, sec: "10.9-10.10 Multiples & SOTP", q: "Transaction multiples are considered more relevant than trading multiples because they:", opts: ["are always lower", "need no comparables", "show some entities' willingness to acquire the asset at that value, making them relatively more authentic than traded prices", "are based on day-to-day market mood"], ans: 2, exp: "Reflect real executed corporate M&A deals where an actual buyer paid money for control." },
  { id: 10132, sec: "10.9-10.10 Multiples & SOTP", q: "Relative valuation reflects current market mood. Therefore, analysts should:", opts: ["ignore peers", "use maximum, minimum and average values and examine history over several years and across peers and industry", "use only the latest single multiple", "avoid using P/E"], ans: 1, exp: "Evaluate cycle-average, maximum, and minimum historical multiples across peers." },
  { id: 10133, sec: "10.9-10.10 Multiples & SOTP", q: "Sum-of-the-Parts (SOTP) valuation is most useful for:", opts: ["conglomerates such as ITC and L&T with different businesses under one umbrella", "single-product companies", "start-ups with no revenue", "banks only"], ans: 0, exp: "Conglomerates operating across distinct unrelated divisions (e.g. tobacco, hotels, software, engineering)." },
  { id: 10134, sec: "10.9-10.10 Multiples & SOTP", q: "Under SOTP, the total value of the group is obtained by:", opts: ["valuing only the largest vertical", "taking the average of the verticals", "valuing each business vertical on earnings and assets and simply summing the values", "applying one consolidated multiple to the group"], ans: 2, exp: "Valuing each business unit independently using sector-specific metrics, then summing them together." },
  { id: 10135, sec: "10.11-10.12 New Age Businesses & Objectivity", q: "Which of the following are cited as new-age valuation parameters in the chapter?", opts: ["NAV and embedded value", "Eyeballs, page views, footfall, ARPU and number of users", "Dividend yield and P/B", "WACC and CAPM"], ans: 1, exp: "Non-financial digital metrics: Monthly Active Users, Eyeballs, ARPU, and Footfalls." },
  { id: 10136, sec: "10.11-10.12 New Age Businesses & Objectivity", q: "As Buffett would say, new-age parameters such as users and eyeballs should:", opts: ["ultimately translate into profits for owners at some point in time", "be ignored in all cases", "translate into higher share price volume", "replace profits as the valuation basis"], ans: 0, exp: "Users and page views have value only if they can eventually be monetized into bottom-line profits." },
  { id: 10137, sec: "10.11-10.12 New Age Businesses & Objectivity", q: "New-age valuations without any visibility of profits would, according to the chapter:", opts: ["be consistent with DCF values", "be unaffected by market sentiment", "be sustained permanently by user growth", "sustain only while people believe the story and a next buyer is available, and may fall like a pack of cards as in the .com boom of 2000-2001"], ans: 3, exp: "Dot-com crash lesson: pure hype-driven metrics collapse once liquidity dries up." },
  { id: 10138, sec: "10.11-10.12 New Age Businesses & Objectivity", q: "Valuation is described as a subjective exercise because:", opts: ["market prices are never available", "all inputs are fixed by law", "the inputs are quite subjective, with no generally accepted standards", "only one method exists"], ans: 2, exp: "Forecast cash flows, growth rates, and cost of capital inherently involve subjective analyst judgement." },
  { id: 10139, sec: "10.11-10.12 New Age Businesses & Objectivity", q: "Complicated quantitative models, in the chapter's view:", opts: ["make valuation precise", "only create a false impression of preciseness", "make valuation timeless", "remove subjectivity"], ans: 1, exp: "Mathematical complexity gives a false illusion of precision while remaining hostage to subjective inputs." },
  { id: 10140, sec: "10.11-10.12 New Age Businesses & Objectivity", q: "Which statement about the timelessness of valuation is correct?", opts: ["Valuation is not timeless and can change dramatically if circumstances of the business change", "Valuation changes only with the stock index", "Valuation never changes if DCF is used", "A valuation remains valid for many years"], ans: 0, exp: "Valuation is never static; economic shocks, competitive threats, and interest rate shifts alter value rapidly." },
  { id: 10141, sec: "10.13 Valuation Considerations", q: "If the earning power of a business is high:", opts: ["earnings are irrelevant", "book value is very important", "P/E cannot be used", "book value of shares could be less important"], ans: 3, exp: "High sustained return on capital diminishes the importance of historical asset book value." },
  { id: 10142, sec: "10.13 Valuation Considerations", q: "For a private owner acquiring a business, the true value of the firm is represented by:", opts: ["book value of equity", "dividends per share", "enterprise value, not market capitalisation", "market capitalisation, not enterprise value"], ans: 2, exp: "The acquirer takes on all outstanding debt and cash, making EV the true cost of acquisition." },
  { id: 10143, sec: "10.13 Valuation Considerations", q: "The P/E of a leveraged firm may be deceptive; the analyst should therefore:", opts: ["look at the debt levels in the business", "ignore debt", "use only dividends", "use only P/E"], ans: 0, exp: "Debt leverage boosts EPS in boom periods while ballooning financial default risk." },
  { id: 10144, sec: "10.13 Valuation Considerations", q: "As per the chapter, an analyst should look at:", opts: ["only the parent's dividends", "consolidated numbers and not just standalone numbers", "only the latest quarter", "only standalone numbers"], ans: 1, exp: "Consolidated figures provide the only complete picture of group liabilities and subsidiary earnings." },
  { id: 10145, sec: "10.13 Valuation Considerations", q: "The chapter suggests focusing on ROE and not EPS because:", opts: ["EPS is always negative", "EPS includes debt", "ROE ignores equity", "EPS does not account for retained earnings"], ans: 3, exp: "EPS growth can occur simply from piling up retained profits without actually improving capital return efficiency." },
  { id: 10146, sec: "10.13 Valuation Considerations", q: "Which statement on ROE and ROCE is correct?", opts: ["Leverage improves ROE but excessive leverage is risky; ROCE reflects the true return on capital, and a wide gap between them should trigger investigation", "ROE is always more reliable than ROCE", "A wide gap between ROE and ROCE is a positive sign", "ROCE can be manipulated by leverage, not ROE"], ans: 0, exp: "A massive spread where ROE is far above ROCE indicates aggressive, dangerous debt leverage." },
  { id: 10147, sec: "10.13 Valuation Considerations", q: "A company's ROE is 30% while its ROCE is only 9%. The best response according to the chapter is to:", opts: ["ignore ROCE", "accept the high ROE as the true return", "use EPS instead", "investigate, since a wide variation between the two may reflect high leverage"], ans: 3, exp: "Investigate immediately; the divergence points toward heavy leverage amplifying equity return." },
  { id: 10148, sec: "10.13 Valuation Considerations", q: "Which of the following is NOT among the considerations listed in 10.13?", opts: ["EV and not market capitalisation is the true value for a private owner", "Focus on ROE and not EPS", "Standalone numbers should be preferred over consolidated numbers", "P/E for a leveraged firm may be deceptive"], ans: 2, exp: "The chapter insists on consolidated figures over standalone numbers." },
  { id: 10149, sec: "10.15 Case Set (Sample Q4)", q: "PE ratio for Company B is higher than that of Company A. Which of the following is a plausible reason?", opts: ["EPS growth rate of B is higher than that of A, and higher growth justifies a higher PE", "B is relatively smaller, and the smaller base justifies a higher PE", "B has high financial leverage, which justifies a higher PE", "None of the above statements is true"], ans: 0, exp: "Company B's EPS growth is 20.1% vs 14.7% for A; superior growth warrants a higher P/E multiple." },
  { id: 10150, sec: "10.15 Case Set (Sample Q4)", q: "Which company appears cheaper on PEG (use expected 2XX9 growth)?", opts: ["A is cheaper: PEG 1.05x vs 0.91x for B", "B is cheaper: PEG 0.91x vs 1.05x for A", "A is cheaper: PEG 2.91x vs 1.07x for B", "B is cheaper: PEG 1.07x vs 2.91x for A"], ans: 1, exp: "Growth A = 14.7%, PEG = 15.4 / 14.7 = 1.05x. Growth B = 20.1%, PEG = 18.2 / 20.1 = 0.91x. Company B is cheaper on growth-adjusted PEG." },
  { id: 10151, sec: "10.15 Case Set (Sample Q4)", q: "Which is closest to the market capitalisation of Company A in 2XX9?", opts: ["Rs.3,046 lakhs", "Rs.30,000 lakhs", "Rs.42,600 lakhs", "None of the above"], ans: 2, exp: "Market Cap = P/E * Net Profit = 15.4 * 2,763.1 = Rs.42,552 lakhs, closest to Rs.42,600 lakhs." },
  { id: 10152, sec: "10.15 Case Set (Sample Q4)", q: "The market cap of Company B is Rs.36,000 lakhs. Which is closest to its EV/EBITDA on the 2XX9 forecast?", opts: ["8.17x", "8.74x", "9.14x", "9.54x"], ans: 3, exp: "EV = 36,000 + 1,626.8 - 57.0 = 37,569.8 lakhs. EV/EBITDA = 37,569.8 / 3,938.8 = 9.54x." },
  { id: 10153, sec: "10.15 Case Set (Sample Q4)", q: "Average peer P/E is 16x. If Company B deserves a 20% premium on 2XX9 EPS of Rs.32.2, fair price is closest to:", opts: ["Rs.428.7", "Rs.514.8", "Rs.617.8", "Rs.643.6"], ans: 2, exp: "Target P/E = 16 * 1.20 = 19.2x. Fair share price = 19.2 * 32.2 = Rs.618.2 (closest to Rs.617.8)." },
  { id: 10154, sec: "10.15 Case Set (Sample Q4)", q: "Fair EV/EBITDA for Company A is 8.5x (2XX9 EBITDA Rs.4,754.6). Which is closest to fair value of its equity?", opts: ["Rs.38,943 lakhs", "Rs.40,415 lakhs", "Rs.41,886 lakhs", "Rs.42,224 lakhs"], ans: 0, exp: "EV = 8.5 * 4,754.6 = 40,414.1 lakhs. Equity = EV - Debt + Cash = 40,414.1 - 1,640.5 + 169.0 = Rs.38,942.6 lakhs." },
  { id: 10155, sec: "10.16 Mixed Questions", q: "Consider: I. Risk-neutral discounts probability-adjusted cash flows at Rf. II. Real-world uses expected cash flows and Rf + premium. III. Both are relative valuation categories. Which are correct?", opts: ["I and II only", "II and III only", "I and III only", "I, II and III"], ans: 0, exp: "Both are intrinsic (DCF) methods, not relative valuation, so III is incorrect." },
  { id: 10156, sec: "10.16 Mixed Questions", q: "Consider: I. Trading multiples come from stock market. II. Transaction multiples come from recent M&A deals. III. Trading multiples are more authentic than transaction multiples. Which are correct?", opts: ["I only", "I and II only", "II and III only", "I, II and III"], ans: 1, exp: "Transaction multiples are considered more authentic because real cash was paid for control, making III false." },
  { id: 10157, sec: "10.16 Mixed Questions", q: "Which of the following statements is INCORRECT?", opts: ["Beta is a proxy for systematic risk", "Gordon growth model can be used where the growth rate is higher than the cost of equity", "FCFF is discounted at WACC", "The terminal value must be discounted further to its present value"], ans: 1, exp: "Gordon growth model mathematically requires perpetual growth rate g to be lower than cost of equity k." },
  { id: 10158, sec: "10.16 Mixed Questions", q: "Which pair is correctly matched?", opts: ["DDM - WACC", "FCFF - cost of equity", "FCFE - cost of equity", "FCFF - risk-free rate"], ans: 2, exp: "FCFE matches with Cost of Equity (Ke). DDM uses Ke, and FCFF uses WACC." },
  { id: 10159, sec: "10.16 Mixed Questions", q: "All of the following are asset-based valuation metrics EXCEPT:", opts: ["PEG ratio", "P/B", "Net asset value", "EV/Capital employed"], ans: 0, exp: "PEG is an earnings-based metric (P/E adjusted for growth), not an asset-based metric." },
  { id: 10160, sec: "10.16 Mixed Questions", q: "Match the metric with its use: Which combination is correct?", opts: ["P/B - real estate; NAV - NBFCs; P/ABV - financial sector", "P/EV - NBFCs; NAV - life insurers", "EV/Capacity - banks; P/B - aviation", "P/B - financial sector; NAV - real estate; P/ABV - NBFCs"], ans: 3, exp: "P/B for banks/financials; NAV for real estate; P/ABV for NBFCs." },
  { id: 10161, sec: "10.16 Mixed Questions", q: "Which of the following is most appropriate for an acquirer seeking a ratio neutral to capital structure in a capital-intensive industry?", opts: ["PEG", "EV/EBITDA", "Dividend yield", "P/E"], ans: 1, exp: "EV/EBITDA removes both debt structure biases and depreciation distortions." },
  { id: 10162, sec: "10.16 Mixed Questions", q: "Which of the following is NOT an earnings-based metric?", opts: ["EV/EBITDA", "P/E", "Net asset value", "Dividend yield"], ans: 2, exp: "Net Asset Value (NAV) is an asset-based metric." },
  { id: 10163, sec: "10.16 Mixed Questions", q: "A valuer uses P/E, P/B and EV/EBITDA of comparable companies. This is:", opts: ["cost-based valuation", "relative valuation, which indicates cheapness or expensiveness rather than absolute value", "real-world valuation", "risk-neutral valuation"], ans: 1, exp: "Peer trading multiple comparison is relative valuation." },
  { id: 10164, sec: "10.16 Mixed Questions", q: "The statement 'Valuations are objective as complex models make them precise' is:", opts: ["correct, if relative valuation is used", "correct, as DCF is objective", "correct, if beta is known", "incorrect, because inputs are subjective and complex models only create a false impression of preciseness"], ans: 3, exp: "Valuation models depend on subjective assumptions; complex formulas provide only an illusion of precision." }
];
